"""Additional planar shape admission for optional early relaxation stopping.

This is not the surface acceptance certificate. Callers must retain footprint,
profile, seam and final-coordinate checks. The metric is scale independent;
the existing absolute positive-corner floor is also required.
"""
import bpy
from . import curved_corner_nodes as c

MIN_CORNER_SHAPE = .25
MAX_EDGE_RATIO = 8.
MAX_AREA_CV = .75


def build(*, step_scale=False):
    name = 'Prochitecture Streets / Quad quality stop certificate v1'
    if step_scale: name += ' / Continuous step scale v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    g.socket('Geometry', 'NodeSocketGeometry')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    for key in ('Minimum Corner Shape', 'Maximum Edge Ratio', 'Area CV'):
        g.socket(key, 'NodeSocketFloat', 'OUTPUT')
    if step_scale: g.socket('Step Scale', 'NodeSocketFloat', 'OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    geometry = inp.outputs['Geometry']
    index = g.node('GeometryNodeInputIndex').outputs[0]
    points = []; quads = 1.
    for corner in range(4):
        loop = g.node('GeometryNodeCornersOfFace'); g.bind(index, loop.inputs['Face Index'])
        loop.inputs['Sort Index'].default_value = corner
        vertex = g.node('GeometryNodeVertexOfCorner'); g.bind(loop.outputs['Corner Index'], vertex.inputs['Corner Index'])
        points.append(c._vec(g, c._sample(g, geometry, g.position(), vertex.outputs['Vertex Index'], 'FLOAT_VECTOR')))
        quads = quads*g.math('COMPARE', loop.outputs['Total'], 4.)
    edges = [c._sub(points[(i+1) % 4], points[i]) for i in range(4)]
    length2 = [c._dot(edge, edge) for edge in edges]
    crosses = [c._cross(edges[i], edges[(i+1) % 4]) for i in range(4)]
    shapes = [2.*crosses[i]/g.math('MAXIMUM', length2[i]+length2[(i+1) % 4], 1e-20) for i in range(4)]
    minimum = crosses[0]; shape = shapes[0]; small = large = length2[0]
    for i in range(1, 4):
        minimum = g.math('MINIMUM', minimum, crosses[i])
        shape = g.math('MINIMUM', shape, shapes[i])
        small = g.math('MINIMUM', small, length2[i]); large = g.math('MAXIMUM', large, length2[i])
    ratio = g.math('SQRT', large/g.math('MAXIMUM', small, 1e-20))
    area = .5*(c._cross(c._sub(points[1], points[0]), c._sub(points[2], points[0]))+
               c._cross(c._sub(points[2], points[0]), c._sub(points[3], points[0])))
    mean = c._stat(g, geometry, area, 'Mean', domain='FACE')
    variance = c._stat(g, geometry, area*area, 'Mean', domain='FACE')-mean*mean
    cv = g.math('SQRT', g.math('MAXIMUM', variance, 0.))/g.math('MAXIMUM', mean, 1e-20)
    min_shape = c._stat(g, geometry, shape, domain='FACE')
    max_ratio = c._stat(g, geometry, ratio, 'Max', domain='FACE')
    pins = g.node('GeometryNodeInputNamedAttribute'); pins.data_type = 'BOOLEAN'
    pins.inputs['Name'].default_value = 'st_cq_fixed'
    size = g.node('GeometryNodeAttributeDomainSize'); size.component = 'MESH'
    g.bind(geometry, size.inputs['Geometry'])
    valid = c._stat(g, geometry, quads*g.math('GREATER_THAN', minimum, 1e-9), domain='FACE')
    valid = valid*g.math('GREATER_THAN', size.outputs['Face Count'], 0.)*c._stat(g, geometry, pins.outputs['Exists'])
    geometric = valid
    valid = valid*(1.-g.math('LESS_THAN', min_shape, MIN_CORNER_SHAPE))
    valid = valid*(1.-g.math('GREATER_THAN', max_ratio, MAX_EDGE_RATIO))
    valid = valid*(1.-g.math('GREATER_THAN', cv, MAX_AREA_CV))
    for key, value in (('Valid', valid), ('Minimum Corner Shape', min_shape),
                       ('Maximum Edge Ratio', max_ratio), ('Area CV', cv)):
        g.bind(value, out.inputs[key])
    if step_scale:
        # Fade each attempted displacement to zero as ALL shape thresholds
        # approach admission. A hard stop must not discard a finite-sized next
        # step at that boundary. Outside a relative 10% band use the unchanged
        # step. Folded/invalid geometry keeps full untangling steps, and every
        # caller still applies the original complete-surface guards.
        deficit = g.math('MAXIMUM', (MIN_CORNER_SHAPE-min_shape)/MIN_CORNER_SHAPE,
                         (max_ratio-MAX_EDGE_RATIO)/MAX_EDGE_RATIO)
        deficit = g.math('MAXIMUM', deficit, (cv-MAX_AREA_CV)/MAX_AREA_CV)
        scale = c.bounded(g, deficit/.1, 0., 1.)
        g.bind(c.choose(g, geometric, scale, 1.), out.inputs['Step Scale'])
    return g.g
